    type->serialize(tlw);
    if (data.has_value()) { data.value()->serialize(tlw); }
    if (front_side.has_value()) { front_side.value()->serialize(tlw); }
    if (reverse_side.has_value()) { reverse_side.value()->serialize(tlw); }
